/**
 * Measure same-camera source-owner versus shell projections generated by
 * Blender. This is objective coverage evidence, not architectural approval:
 * missing pixels may be intentional nonstructural detail or a real shell hole.
 * Defaults to first-floor; use --profile for another disabled shell candidate.
 */
import { createHash } from 'node:crypto'
import { readFile, writeFile } from 'node:fs/promises'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import sharp from 'sharp'
import { requestedShellVisualQaProfile, shellVisualQaPaths } from './lib/shell-visual-qa-profile.mjs'

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url))
const VIEWER_ROOT = resolve(SCRIPT_DIR, '..')
const PROFILE = requestedShellVisualQaProfile(process.argv)
const { candidateRoot: CANDIDATE_ROOT, indexPath: INDEX_PATH, outputRoot: QA_ROOT } = shellVisualQaPaths(VIEWER_ROOT, PROFILE)
const VIEWS = ['front', 'back', 'left', 'right', 'top', 'bottom', 'grazing']
const FOREGROUND_LUMA = 60

async function sha256File(path) {
  return createHash('sha256').update(await readFile(path)).digest('hex')
}

async function imageMask(path) {
  const input = await readFile(path)
  const { data, info } = await sharp(input).removeAlpha().raw().toBuffer({ resolveWithObject: true })
  const mask = new Uint8Array(info.width * info.height)
  let pixels = 0
  for (let index = 0; index < mask.length; index += 1) {
    const offset = index * info.channels
    const luma = data[offset] * 0.2126 + data[offset + 1] * 0.7152 + data[offset + 2] * 0.0722
    if (luma <= FOREGROUND_LUMA) continue
    mask[index] = 1
    pixels += 1
  }
  return {
    input,
    mask,
    pixels,
    width: info.width,
    height: info.height,
    sha256: createHash('sha256').update(input).digest('hex'),
  }
}

function compareMasks(reference, candidate) {
  if (reference.width !== candidate.width || reference.height !== candidate.height) {
    throw new Error('Projection images do not share exact dimensions')
  }
  let intersection = 0
  let union = 0
  for (let index = 0; index < reference.mask.length; index += 1) {
    const a = reference.mask[index]
    const b = candidate.mask[index]
    if (a && b) intersection += 1
    if (a || b) union += 1
  }
  return {
    referencePixels: reference.pixels,
    candidatePixels: candidate.pixels,
    intersectionPixels: intersection,
    referenceOnlyPixels: reference.pixels - intersection,
    candidateOnlyPixels: candidate.pixels - intersection,
    referenceCoverage: reference.pixels ? intersection / reference.pixels : 0,
    candidatePrecision: candidate.pixels ? intersection / candidate.pixels : 0,
    intersectionOverUnion: union ? intersection / union : 0,
  }
}

const [renderReport, preparedInputs, candidateIndex] = await Promise.all([
  readFile(resolve(QA_ROOT, 'render-report.json'), 'utf8').then(JSON.parse),
  readFile(resolve(QA_ROOT, 'prepared-inputs.json'), 'utf8').then(JSON.parse),
  readFile(INDEX_PATH, 'utf8').then(JSON.parse),
])
if (candidateIndex.enabled !== false || candidateIndex.shellCompletion?.candidateBuilt !== true) {
  throw new Error(`Expected the disabled completed ${PROFILE.title.toLowerCase()} shell candidate`)
}
if (candidateIndex.owner?.nodeName !== PROFILE.ownerName) {
  throw new Error(`Candidate owner is ${candidateIndex.owner?.nodeName}, expected ${PROFILE.ownerName}`)
}
if (candidateIndex.shellCompletion.ready !== false) throw new Error('Shell candidate must remain ready=false')
if (preparedInputs.schema !== 'IOM_OWNER_SHELL_VISUAL_QA_PREPARED_INPUTS' || preparedInputs.version !== 1) {
  throw new Error('Prepared-input evidence schema is invalid')
}
if (preparedInputs.profile?.slug !== PROFILE.slug || preparedInputs.profile?.ownerName !== PROFILE.ownerName) {
  throw new Error('Prepared-input evidence belongs to a different profile')
}
if (preparedInputs.ready !== false || preparedInputs.activationApproved !== false) {
  throw new Error('Prepared-input evidence is not fail-closed')
}
if (preparedInputs.candidateIndex?.sha256 !== await sha256File(INDEX_PATH)) {
  throw new Error('Candidate index changed after QA input preparation')
}
if (renderReport.resolution !== 960) throw new Error(`Expected 960 px source-vs-shell renders, got ${renderReport.resolution}`)
if (renderReport.schema !== 'iom-repeat-lod-blender-visual-qa-v1') throw new Error('Unexpected Blender render-report schema')
if (renderReport.status !== 'renders-generated-manual-approval-required') throw new Error('Blender render report is not fail-closed')
const expectedInputs = ['web-source', 'web-shell', 'quest-source', 'quest-shell'].map((label) => ({
  label,
  input: resolve(QA_ROOT, label.endsWith('source')
    ? `${label.slice(0, -'-source'.length)}-source-owner-geometry-review.glb`
    : `${label.slice(0, -'-shell'.length)}-shell-geometry-review.glb`),
}))
if (renderReport.candidates?.length !== expectedInputs.length) throw new Error('Blender render report does not contain four candidates')
for (let index = 0; index < expectedInputs.length; index += 1) {
  const expected = expectedInputs[index]
  const actual = renderReport.candidates[index]
  if (actual.label !== expected.label || resolve(actual.input) !== expected.input) {
    throw new Error(`Blender candidate ${index} is stale or belongs to another profile`)
  }
  const [variant, kind] = expected.label.split('-')
  const preparedKey = kind === 'source' ? 'preparedSourceOwner' : 'preparedShell'
  const preparedEvidence = preparedInputs.variants?.[variant]?.[preparedKey]
  if (!preparedEvidence) throw new Error(`Prepared-input evidence is missing ${expected.label}`)
  if (actual.inputSha256 === undefined && PROFILE.slug !== 'first-floor') {
    throw new Error(`Blender candidate ${expected.label} does not pin its input SHA-256`)
  }
  if (actual.inputSha256 !== undefined && (
    actual.inputSha256 !== preparedEvidence.sha256 || actual.inputBytes !== preparedEvidence.bytes
  )) {
    throw new Error(`Blender candidate ${expected.label} was rendered from stale input bytes`)
  }
  for (const view of VIEWS) {
    if (actual.renders?.[view] !== `${expected.label}-${view}.png`) {
      throw new Error(`Blender candidate ${expected.label} is missing ${view}`)
    }
  }
}
for (const variant of ['web', 'quest']) {
  const prepared = preparedInputs.variants?.[variant]
  if (!prepared) throw new Error(`Prepared-input evidence is missing ${variant}`)
  for (const key of ['preparedSourceOwner', 'preparedShell']) {
    if (prepared[key]?.sha256 !== await sha256File(prepared[key]?.path)) {
      throw new Error(`${variant} ${key} changed after preparation`)
    }
  }
}
const results = { web: {}, quest: {} }
const parity = {}

for (const variant of ['web', 'quest']) {
  for (const view of VIEWS) {
    const sourcePath = resolve(QA_ROOT, `${variant}-source-${view}.png`)
    const shellPath = resolve(QA_ROOT, `${variant}-shell-${view}.png`)
    const [source, shell] = await Promise.all([imageMask(sourcePath), imageMask(shellPath)])
    if (!source.pixels || !shell.pixels) throw new Error(`${variant} ${view} has an empty foreground mask`)
    results[variant][view] = {
      source: { file: `${variant}-source-${view}.png`, sha256: source.sha256 },
      shell: { file: `${variant}-shell-${view}.png`, sha256: shell.sha256 },
      ...compareMasks(source, shell),
    }
  }
}

for (const view of VIEWS) {
  const [web, quest] = await Promise.all([
    imageMask(resolve(QA_ROOT, `web-shell-${view}.png`)),
    imageMask(resolve(QA_ROOT, `quest-shell-${view}.png`)),
  ])
  parity[view] = compareMasks(web, quest)
}

const flattened = Object.values(results).flatMap((variant) => Object.values(variant))
const parityValues = Object.values(parity)
const evidencePins = {
  candidateIndex: { path: INDEX_PATH, sha256: await sha256File(INDEX_PATH) },
  preparedInputs: {
    path: resolve(QA_ROOT, 'prepared-inputs.json'),
    sha256: await sha256File(resolve(QA_ROOT, 'prepared-inputs.json')),
  },
  blenderRenderReport: {
    path: resolve(QA_ROOT, 'render-report.json'),
    sha256: await sha256File(resolve(QA_ROOT, 'render-report.json')),
  },
  preparedGlbs: Object.fromEntries(['web', 'quest'].map((variant) => [variant, {
    sourceOwner: preparedInputs.variants[variant].preparedSourceOwner,
    shell: preparedInputs.variants[variant].preparedShell,
  }])),
  blenderInputPinsVerified: renderReport.candidates.every((candidate) => Boolean(candidate.inputSha256)),
}
const report = {
  schema: PROFILE.auditSchema,
  version: 1,
  generatedAt: new Date().toISOString(),
  profile: { slug: PROFILE.slug, title: PROFILE.title, ownerName: PROFILE.ownerName },
  candidateRoot: CANDIDATE_ROOT,
  renderer: renderReport.renderer,
  resolution: renderReport.resolution,
  views: VIEWS,
  foregroundLumaThreshold: FOREGROUND_LUMA,
  evidencePins,
  sourceVsShell: results,
  shellVariantParity: parity,
  summary: {
    minimumSourceCoverage: Math.min(...flattened.map((entry) => entry.referenceCoverage)),
    meanSourceCoverage: flattened.reduce((sum, entry) => sum + entry.referenceCoverage, 0) / flattened.length,
    minimumCandidatePrecision: Math.min(...flattened.map((entry) => entry.candidatePrecision)),
    minimumWebQuestShellIoU: Math.min(...parityValues.map((entry) => entry.intersectionOverUnion)),
    meanWebQuestShellIoU: parityValues.reduce((sum, entry) => sum + entry.intersectionOverUnion, 0) / parityValues.length,
  },
  status: 'machine-projection-evidence-complete-manual-structural-coverage-review-required',
  ready: false,
  activationApproved: false,
  limitation: 'Projection coverage cannot classify missing pixels as intentional furniture/transparency omission versus an architectural hole.',
}

const output = resolve(QA_ROOT, 'projection-audit.json')
await writeFile(output, JSON.stringify(report, null, 2))
console.log(JSON.stringify({ output, summary: report.summary, status: report.status }, null, 2))
